import { R, X, lesson, mcq, numeric, short } from './helpers';
import type { Lesson } from '@/lib/types';

/**
 * ROBOTICS.
 *
 * The ROBOTICS track: where mechanics, electronics, embedded firmware and
 * control finally combine into a machine that senses, decides and acts. The
 * mathematics here is the real thing - homogeneous transforms, Jacobians,
 * odometry integrals - because every later track (ROS 2, navigation, humanoid)
 * assumes you can do it rather than call a library.
 *
 * Order: architecture -> kinematics -> inverse kinematics -> Jacobians ->
 * dynamics -> mobile robot kinematics and odometry -> path planning ->
 * simulation and the sim-to-real gap.
 */
